import * as React from "react";

import { cn } from "../lib/utils";
import { Breadcrumb, type BreadcrumbCrumb } from "./breadcrumb";

import styles from "./page-header.module.css";

export type PageHeaderProps = Omit<React.ComponentPropsWithoutRef<"header">, "title"> & {
  title: React.ReactNode;
  size?: "lg" | "md";
  mono?: boolean;
  breadcrumb?: readonly BreadcrumbCrumb[];
  maxItems?: number;
  badges?: React.ReactNode;
  description?: React.ReactNode;
  actions?: React.ReactNode;
  tabs?: React.ReactNode;
  media?: React.ReactNode;
};

export function PageHeader({
  title,
  size = "lg",
  mono = false,
  breadcrumb,
  maxItems,
  badges,
  description,
  actions,
  tabs,
  media,
  className,
  ref,
  ...props
}: PageHeaderProps & { ref?: React.Ref<HTMLElement> }) {
  return (
    <header
      ref={ref}
      data-slot="page-header"
      data-size={size}
      className={cn(styles.header, className)}
      {...props}
    >
      {breadcrumb && breadcrumb.length > 0 && (
        <Breadcrumb
          aria-label="Page path"
          items={breadcrumb}
          maxItems={maxItems}
          lastIsCurrent={false}
          className={styles.trail}
        />
      )}
      <div className={styles.main}>
        {media && <span className={styles.media}>{media}</span>}
        <div className={styles.copy}>
          <div className={styles.titleLine}>
            <h1 className={cn(styles.title, mono && styles.mono)}>{title}</h1>
            {badges && (
              <span data-slot="page-header-badges" className={styles.badges}>
                {badges}
              </span>
            )}
          </div>
          {description && <p className={styles.description}>{description}</p>}
        </div>
        {actions && <div className={styles.actions}>{actions}</div>}
      </div>
      {tabs && <div className={styles.tabs}>{tabs}</div>}
    </header>
  );
}
PageHeader.displayName = "PageHeader";

.header {
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.trail {
  margin-bottom: var(--cipher-space-8);
}
.main {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: var(--cipher-space-16) var(--cipher-space-24);
  min-width: 0;
}
.media {
  display: inline-flex;
  flex: none;
  width: var(--cipher-size-control-lg);
  height: var(--cipher-size-control-lg);
}
.copy {
  display: flex;
  flex: 1 1 var(--cipher-size-text-min);
  flex-direction: column;
  gap: var(--cipher-space-10);
  min-width: var(--cipher-size-text-min);
}
.header[data-size="md"] .copy {
  gap: var(--cipher-space-8);
}
.titleLine {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--cipher-space-8) var(--cipher-space-12);
  min-width: 0;
}
.title {
  margin: 0;
  min-width: 0;
  overflow-wrap: anywhere;
  color: var(--cipher-ink);
  font-family: var(--cipher-type-display-font-family);
  font-size: var(--cipher-type-display-font-size);
  line-height: var(--cipher-type-display-line-height);
  font-weight: var(--cipher-type-display-font-weight);
  letter-spacing: var(--cipher-type-display-letter-spacing);
}
.header[data-size="md"] .title {
  font-family: var(--cipher-type-title-lg-font-family);
  font-size: var(--cipher-type-title-lg-font-size);
  line-height: var(--cipher-type-title-lg-line-height);
  font-weight: var(--cipher-type-title-lg-font-weight);
  letter-spacing: var(--cipher-type-title-lg-letter-spacing);
}
.mono {
  font-family: var(--cipher-font-mono);
  letter-spacing: 0;
}
.header[data-size="md"] .mono {
  font-family: var(--cipher-font-mono);
}
.badges {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--cipher-space-6);
}
.description {
  margin: 0;
  max-width: var(--cipher-size-measure-prose);
  color: var(--cipher-muted);
  font-family: var(--cipher-type-body-lg-font-family);
  font-size: var(--cipher-type-body-lg-font-size);
  line-height: var(--cipher-type-body-lg-line-height);
  font-weight: var(--cipher-type-body-lg-font-weight);
  letter-spacing: var(--cipher-type-body-lg-letter-spacing);
}
.actions {
  display: flex;
  flex: 0 1 auto;
  flex-wrap: wrap;
  max-width: 100%;
  align-items: center;
  gap: var(--cipher-space-8);
  min-height: var(--cipher-type-display-line-height);
}
.header[data-size="md"] .actions {
  min-height: var(--cipher-type-title-lg-line-height);
}
.tabs {
  margin-top: var(--cipher-space-24);
}
